mapper.select:
select s.*
from student s


        and s.student_id = #{studentId}


        and s.student_name like concat('%', #{studentName}, '%')


        and gender = #{gender}


        and create_time between #{begin} and #{end}


order by s.create_time desc

mapper.update:
update student
set student_name = #{studentName}, gender = #{gender}
where student_id = #{studentId}
